//Ce fichier est a retirer si la fonction 3d n'est pas utiliser
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

export default class {
  constructor(element) {
    this.canvas = element;
    this.size = {
      width: 100,
      height: 100,
    };
    //- SCENE -//
    this.scene = new THREE.Scene();
    this.clock = new THREE.Clock();

    this.init();
  }
  init() {

    this.createCamera();
    this.createObjects();
    this.createRenderer();
    this.animate();
  }

  createCamera() {
    this.camera = new THREE.PerspectiveCamera(
      180,
      this.size.width / this.size.height,
      0.1,
      1,
    );
    this.camera.position.x = 5;
    this.camera.position.y = -1;
    //this.camera.position.z = -30;
    this.scene.add(this.camera);
  }

  createObjects() {
    //Structure
    
    const boxGeo = new THREE.BoxGeometry(10, 10, 10, 10, 10, 10);
    const materialBox = new THREE.MeshMatcapMaterial({
      color: "#FB62F6",
      //wireframe: true,
    });
    this.cube = new THREE.Mesh(boxGeo, materialBox);

    this.scene.add(
      this.cube
    );
    
    const loader = new GLTFLoader();

    loader.load( '/assets/3d/contact.glb', function ( gltf ) {
      this.scene.add( gltf.scene );
    }, undefined, function ( error ){
      console.error( error );
    });

    
  }

  createRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
    });

    this.renderer.setSize(this.size.width, this.size.height);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.render(this.scene, this.camera);
  }

  animate() {
    const elapseTime = this.clock.getElapsedTime();

    window.requestAnimationFrame(this.animate.bind(this));

    this.renderer.render(this.scene, this.camera);
  }
}
